import sys

MOD = 998244353
A = 65  # ord('A')
B = 66  # ord('B')

class DSU:
    __slots__ = ('parent', 'rank', 'parity', 'comps')
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.parity = [0] * n
        self.comps = n

    def find(self, x):
        if self.parent[x] == x:
            return x, 0
        r, p = self.find(self.parent[x])
        self.parity[x] ^= p
        self.parent[x] = r
        return r, self.parity[x]

    def union(self, x, y, w):
        rx, px = self.find(x)
        ry, py = self.find(y)
        if rx == ry:
            return (px ^ py) == w
        if self.rank[rx] < self.rank[ry]:
            self.parent[rx] = ry
            self.parity[rx] = px ^ py ^ w
        else:
            self.parent[ry] = rx
            self.parity[ry] = px ^ py ^ w
            if self.rank[rx] == self.rank[ry]:
                self.rank[rx] += 1
        self.comps -= 1
        return True


def solve():
    sys.setrecursionlimit(1000000)
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    T = int(next(it))
    out = []

    for _ in range(T):
        H = int(next(it))
        W = int(next(it))
        S = [next(it) for _ in range(H)]

        row_ok = True
        col_cnt = [0] * W
        for row in S:
            cntA = 0
            for j, ch in enumerate(row):
                if ch == A:
                    cntA += 1
                    col_cnt[j] += 1
            if cntA & 1:
                row_ok = False

        if not row_ok:
            out.append(b"0")
            continue

        col_ok = True
        for c in col_cnt:
            if c & 1:
                col_ok = False
                break

        if not col_ok:
            out.append(b"0")
            continue

        N = H + W
        dsu = DSU(N)
        consistent = True
        col_xor = [0] * W

        for i in range(H):
            row = S[i]
            a0 = 1 if row[0] == A else 0
            row_xor = 0
            for j in range(W):
                ch = row[j]
                a = 1 if ch == A else 0

                if j == 0:
                    row_part = a0
                else:
                    row_part = row_xor

                if i == 0:
                    col_part = a
                else:
                    col_part = col_xor[j]

                if ch == B:
                    b = 1 ^ row_part ^ col_part
                    if not dsu.union(i, H + j, b):
                        consistent = False
                        break

                if j >= 1:
                    row_xor ^= a

            if not consistent:
                break

            if i >= 1:
                for j in range(W):
                    if row[j] == A:
                        col_xor[j] ^= 1

        if not consistent:
            out.append(b"0")
        else:
            ans = pow(2, dsu.comps, MOD)
            out.append(str(ans).encode())

    sys.stdout.buffer.write(b"\n".join(out))


if __name__ == "__main__":
    solve()

import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    N = next(it)
    M = next(it)
    Q = next(it)

    A = [0] * (M + 1)
    B = [0] * (M + 1)
    persons_by_type = [[], []]

    for i in range(1, M + 1):
        S = next(it)
        T = next(it)
        if S < T:
            a, b = S, T
            t = 0
        else:
            a, b = T, S
            t = 1
        A[i] = a
        B[i] = b
        persons_by_type[t].append((i, a, b))

    # Shared left/right endpoint conflicts
    conflict_max = [0] * (M + 1)
    last_a = [0] * (N + 2)
    last_b = [0] * (N + 2)
    for i in range(1, M + 1):
        a = A[i]
        b = B[i]
        shared = last_a[a] if last_a[a] > last_b[b] else last_b[b]
        conflict_max[i] = shared
        last_a[a] = i
        last_b[b] = i

    INF = N + 1

    def process_sweep(persons, is_A):
        if not persons:
            return

        events = []
        for i, a, b in persons:
            val = b if is_A else a
            # insert at a+1, order 1
            events.append((a + 1, 1, i, val, 0))
            # remove at b, order 0
            events.append((b, 0, i, 0, 0))
            # query at a (if A) or b (if B), order 2
            qx = a if is_A else b
            y = b if is_A else a
            bound = i - 1
            events.append((qx, 2, i, y, bound))

        events.sort(key=lambda e: (e[0], e[1]))

        size = 1
        while size < M:
            size <<= 1

        neutral = INF if is_A else -1
        tree = [neutral] * (2 * size)

        def update(idx, val):
            pos = size + idx - 1
            tree[pos] = val
            pos >>= 1
            if is_A:
                while pos:
                    left = pos * 2
                    right = left + 1
                    tree[pos] = tree[left] if tree[left] < tree[right] else tree[right]
                    pos >>= 1
            else:
                while pos:
                    left = pos * 2
                    right = left + 1
                    tree[pos] = tree[left] if tree[left] > tree[right] else tree[right]
                    pos >>= 1

        def query(bound, y):
            if bound <= 0:
                return 0
            l = size
            r = size + bound
            left_nodes = []
            right_nodes = []
            while l < r:
                if l & 1:
                    left_nodes.append(l)
                    l += 1
                if r & 1:
                    r -= 1
                    right_nodes.append(r)
                l >>= 1
                r >>= 1

            if is_A:
                for node in right_nodes:
                    if tree[node] < y:
                        while node < size:
                            rc = node * 2 + 1
                            if tree[rc] < y:
                                node = rc
                            else:
                                node = node * 2
                        return node - size + 1
                for node in reversed(left_nodes):
                    if tree[node] < y:
                        while node < size:
                            rc = node * 2 + 1
                            if tree[rc] < y:
                                node = rc
                            else:
                                node = node * 2
                        return node - size + 1
            else:
                for node in right_nodes:
                    if tree[node] > y:
                        while node < size:
                            rc = node * 2 + 1
                            if tree[rc] > y:
                                node = rc
                            else:
                                node = node * 2
                        return node - size + 1
                for node in reversed(left_nodes):
                    if tree[node] > y:
                        while node < size:
                            rc = node * 2 + 1
                            if tree[rc] > y:
                                node = rc
                            else:
                                node = node * 2
                        return node - size + 1
            return 0

        for e in events:
            _, order, i, val, bound = e
            if order == 0:      # remove
                update(i, neutral)
            elif order == 1:    # insert
                update(i, val)
            else:               # query
                ans = query(bound, val)
                if ans > conflict_max[i]:
                    conflict_max[i] = ans

    process_sweep(persons_by_type[0], True)
    process_sweep(persons_by_type[0], False)
    process_sweep(persons_by_type[1], True)
    process_sweep(persons_by_type[1], False)

    # Prefix maximum of conflict_max
    g = [0] * (M + 1)
    for i in range(1, M + 1):
        prev = g[i - 1]
        cur = conflict_max[i]
        g[i] = prev if prev > cur else cur

    out = []
    for _ in range(Q):
        L = next(it)
        R = next(it)
        if L > g[R]:
            out.append("Yes")
        else:
            out.append("No")

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # Positive products only (subsequences without zeros)
        OFFSET = 2000
        dp0 = [0] * (limit + 1)  # even length subsequences
        dp1 = [0] * (limit + 1)  # odd length subsequences

        for x in nums:
            if x <= 0 or x > limit:
                continue

            new0 = dp0[:]
            new1 = dp1[:]

            # Start a new subsequence with x
            new1[x] |= 1 << (x + OFFSET)

            for p in range(1, limit // x + 1):
                src0 = dp0[p]
                if src0:
                    new1[p * x] |= (src0 << x)  # even -> odd, add x
                src1 = dp1[p]
                if src1:
                    new0[p * x] |= (src1 >> x)  # odd -> even, subtract x

            dp0, dp1 = new0, new1

        bit = k + OFFSET
        if 0 <= bit <= 2 * OFFSET:
            mask = 1 << bit
            for p in range(limit, 0, -1):
                if (dp0[p] & mask) or (dp1[p] & mask):
                    return p

        # Check whether any subsequence containing at least one zero has alternating sum k
        states = {(0, 0, False)}  # (sum, parity, hasZero)
        for x in nums:
            new_states = set(states)  # skip this element
            if x == 0:
                for s, par, hz in states:
                    new_states.add((s, 1 - par, True))
            else:
                for s, par, hz in states:
                    if par == 0:
                        ns = s + x
                    else:
                        ns = s - x
                    new_states.add((ns, 1 - par, hz))
            states = new_states

        for s, par, hz in states:
            if s == k and hz:
                return 0

        return -1

