import math
from bisect import bisect_right

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    q = data[0]
    queries = data[1:1 + q]
    max_a = max(queries)
    limit = math.isqrt(max_a)

    omega = [0] * (limit + 1)
    is_comp = [False] * (limit + 1)
    primes = []

    for i in range(2, limit + 1):
        if not is_comp[i]:
            primes.append(i)
            omega[i] = 1

        oi = omega[i]
        for p in primes:
            v = i * p
            if v > limit:
                break
            is_comp[v] = True
            if i % p == 0:
                omega[v] = oi
                break
            else:
                omega[v] = oi + 1

    numbers = []
    for i in range(2, limit + 1):
        if omega[i] == 2:
            numbers.append(i * i)

    out = []
    for a in queries:
        idx = bisect_right(numbers, a) - 1
        out.append(str(numbers[idx]))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()

import sys

def solve():
    data = sys.stdin.read().split()
    it = iter(data)
    T = int(next(it))
    out = []
    INF = 10**18
    for _ in range(T):
        N = int(next(it)); K = int(next(it))
        M = 2 * K
        items = []
        for _ in range(N):
            x = int(next(it)); y = int(next(it)); z = int(next(it))
            items.append((x, y, z))
        m = [max(x, y, z) for x, y, z in items]
        v = items

        idx_sorted = sorted(range(N), key=lambda i: m[i], reverse=True)
        selected = idx_sorted[:M]
        unselected = idx_sorted[M:]
        base_sum = sum(m[i] for i in selected)

        # initial best-colour assignment for parity
        counts = [0, 0, 0]
        for i in selected:
            mi = m[i]
            if v[i][0] == mi:
                counts[0] += 1
            elif v[i][1] == mi:
                counts[1] += 1
            else:
                counts[2] += 1

        parity = [c % 2 for c in counts]
        if parity[0] == 0 and parity[1] == 0 and parity[2] == 0:
            out.append(str(base_sum))
            continue

        odd = [c for c in range(3) if parity[c] == 1]
        A, B = odd[0], odd[1]
        C = 3 - A - B

        # ---------- precomputations ----------
        sel_list = [[] for _ in range(3)]
        minM = [INF, INF, INF]
        secondMinM = [INF, INF, INF]
        idx_minM = [-1, -1, -1]
        idx_secondMinM = [-1, -1, -1]

        bestFlip = [[INF] * 3 for _ in range(3)]
        secondBestFlip = [[INF] * 3 for _ in range(3)]
        idx_bestFlip = [[-1] * 3 for _ in range(3)]
        idx_secondBestFlip = [[-1] * 3 for _ in range(3)]

        for i in selected:
            mi = m[i]
            for c in range(3):
                if v[i][c] == mi:
                    sel_list[c].append(i)
                    val = mi
                    if val < minM[c]:
                        secondMinM[c] = minM[c]
                        idx_secondMinM[c] = idx_minM[c]
                        minM[c] = val
                        idx_minM[c] = i
                    elif val < secondMinM[c]:
                        secondMinM[c] = val
                        idx_secondMinM[c] = i
                    for t in range(3):
                        val2 = mi - v[i][t]
                        if val2 < bestFlip[c][t]:
                            secondBestFlip[c][t] = bestFlip[c][t]
                            idx_secondBestFlip[c][t] = idx_bestFlip[c][t]
                            bestFlip[c][t] = val2
                            idx_bestFlip[c][t] = i
                        elif val2 < secondBestFlip[c][t]:
                            secondBestFlip[c][t] = val2
                            idx_secondBestFlip[c][t] = i

        maxUnsel = [-INF] * 3
        secondMaxUnsel = [-INF] * 3
        idx_maxUnsel = [-1] * 3
        idx_secondMaxUnsel = [-1] * 3

        for j in unselected:
            for t in range(3):
                val = v[j][t]
                if val > maxUnsel[t]:
                    secondMaxUnsel[t] = maxUnsel[t]
                    idx_secondMaxUnsel[t] = idx_maxUnsel[t]
                    maxUnsel[t] = val
                    idx_maxUnsel[t] = j
                elif val > secondMaxUnsel[t]:
                    secondMaxUnsel[t] = val
                    idx_secondMaxUnsel[t] = j

        def get_minM_excl(c, excl_i):
            if minM[c] == INF:
                return INF
            if idx_minM[c] != excl_i:
                return minM[c]
            return secondMinM[c]

        def get_bestFlip_excl(c, t, excl_i):
            if bestFlip[c][t] == INF:
                return INF
            if idx_bestFlip[c][t] != excl_i:
                return bestFlip[c][t]
            return secondBestFlip[c][t]

        def get_maxPair(t1, t2):
            best1 = maxUnsel[t1]
            best2 = maxUnsel[t2]
            if best1 == -INF or best2 == -INF:
                return -INF
            idx1 = idx_maxUnsel[t1]
            idx2 = idx_maxUnsel[t2]
            if idx1 != idx2:
                return best1 + best2
            res = -INF
            if secondMaxUnsel[t2] > -INF:
                res = max(res, best1 + secondMaxUnsel[t2])
            if secondMaxUnsel[t1] > -INF:
                res = max(res, secondMaxUnsel[t1] + best2)
            return res

        def single_cost(u, vv):
            res = INF
            if bestFlip[u][vv] < INF:
                res = min(res, bestFlip[u][vv])
            if bestFlip[vv][u] < INF:
                res = min(res, bestFlip[vv][u])
            if minM[u] < INF and maxUnsel[vv] > -INF:
                res = min(res, minM[u] - maxUnsel[vv])
            if minM[vv] < INF and maxUnsel[u] > -INF:
                res = min(res, minM[vv] - maxUnsel[u])
            return res

        cost_one = single_cost(A, B)

        P_types = [
            (A, C, True),   # flip A->C
            (C, A, True),   # flip C->A
            (A, C, False),  # rep A->C
            (C, A, False),  # rep C->A
        ]
        Q_types = [
            (C, B, True),   # flip C->B
            (B, C, True),   # flip B->C
            (C, B, False),  # rep C->B
            (B, C, False),  # rep B->C
        ]

        cost_two = INF
        for c1, t1, is_flip1 in P_types:
            for c2, t2, is_flip2 in Q_types:
                if is_flip1 and is_flip2:
                    for i1 in sel_list[c1]:
                        cost1 = m[i1] - v[i1][t1]
                        cost2 = get_bestFlip_excl(c2, t2, i1)
                        if cost2 < INF:
                            total = cost1 + cost2
                            if total < cost_two:
                                cost_two = total
                elif is_flip1 and not is_flip2:
                    for i1 in sel_list[c1]:
                        cost1 = m[i1] - v[i1][t1]
                        min_i2 = get_minM_excl(c2, i1)
                        if min_i2 < INF and maxUnsel[t2] > -INF:
                            cost2 = min_i2 - maxUnsel[t2]
                            total = cost1 + cost2
                            if total < cost_two:
                                cost_two = total
                elif not is_flip1 and is_flip2:
                    for i2 in sel_list[c2]:
                        cost2 = m[i2] - v[i2][t2]
                        min_i1 = get_minM_excl(c1, i2)
                        if min_i1 < INF and maxUnsel[t1] > -INF:
                            cost1 = min_i1 - maxUnsel[t1]
                            total = cost1 + cost2
                            if total < cost_two:
                                cost_two = total
                else:
                    max_pair = get_maxPair(t1, t2)
                    if max_pair > -INF:
                        for i1 in sel_list[c1]:
                            min_i2 = get_minM_excl(c2, i1)
                            if min_i2 < INF:
                                total = m[i1] + min_i2 - max_pair
                                if total < cost_two:
                                    cost_two = total

        min_fix = min(cost_one, cost_two)
        ans = base_sum - min_fix
        out.append(str(ans))

    sys.stdout.write("\n".join(out))

