import sys
from collections import deque

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    S = data[1]
    T = data[2]

    g = {}
    for s, t in zip(S, T):
        if s in g:
            if g[s] != t:
                print(-1)
                return
        else:
            g[s] = t

    A = set(S)
    B = 0
    V = set()
    for a in A:
        if g[a] != a:
            B += 1
            V.add(a)

    # Impossibility check: all 26 letters appear in S, g is injective,
    # and there is at least one non-fixed letter. Then no safe operation exists.
    if len(A) == 26:
        targets = set(g[a] for a in A)
        if len(targets) == len(A) and B > 0:
            print(-1)
            return

    # Build directed graph on V: a -> g[a] if g[a] in V
    adj = {}
    indeg = {v: 0 for v in V}
    for a in V:
        if g[a] in V:
            adj[a] = g[a]
            indeg[g[a]] += 1
        else:
            adj[a] = None

    # Remove acyclic vertices using Kahn's algorithm
    q = deque()
    for v in V:
        if indeg[v] == 0:
            q.append(v)

    removed = set()
    while q:
        u = q.popleft()
        removed.add(u)
        v = adj.get(u)
        if v is not None:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)

    remaining = V - removed

    # Original indegree within V, needed to detect pure cycles
    orig_indeg = {v: 0 for v in V}
    for a in V:
        if g[a] in V:
            orig_indeg[g[a]] += 1

    visited = set()
    pure_cycles = 0

    for v in remaining:
        if v not in visited:
            cur = v
            cycle = []
            while cur not in visited:
                visited.add(cur)
                cycle.append(cur)
                cur = adj[cur]
                if cur is None:
                    break

            is_pure = True
            for node in cycle:
                if orig_indeg[node] != 1:
                    is_pure = False
                    break
            if is_pure:
                pure_cycles += 1

    ans = B + pure_cycles
    print(ans)


