import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, K = data[0], data[1]
    A = data[2:2 + N]

    # Binomial coefficients up to K
    C = [[0] * (K + 1) for _ in range(K + 1)]
    for n in range(K + 1):
        C[n][0] = C[n][n] = 1
        for r in range(1, n):
            C[n][r] = (C[n - 1][r - 1] + C[n - 1][r]) % MOD

    # cum[d] = sum of P_i^d for already processed i
    cum = [0] * (K + 1)
    ans = 0
    pref = 0
    powers = [0] * (K + 1)

    for j in range(N + 1):
        if j > 0:
            pref = (pref + A[j - 1]) % MOD

        powers[0] = 1
        for d in range(1, K + 1):
            powers[d] = powers[d - 1] * pref % MOD

        for t in range(K + 1):
            term = C[K][t] * powers[t] % MOD * cum[K - t] % MOD
            if (K - t) & 1:
                ans = (ans - term) % MOD
            else:
                ans = (ans + term) % MOD

        for d in range(K + 1):
            cum[d] = (cum[d] + powers[d]) % MOD

    print(ans % MOD)

if __name__ == "__main__":
    main()

