from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_non_beautiful(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))
            m = len(digits)

            @lru_cache(maxsize=None)
            def dp(pos: int, sum_digits: int, prod_digits: int, started: bool, tight: bool) -> int:
                if pos == m:
                    return 1 if started and prod_digits % sum_digits != 0 else 0

                limit = digits[pos] if tight else 9
                total = 0

                for d in range(limit + 1):
                    next_tight = tight and (d == limit)

                    if not started:
                        if d == 0:
                            total += dp(pos + 1, 0, 1, False, next_tight)
                        else:
                            total += dp(pos + 1, d, d, True, next_tight)
                    else:
                        if d == 0:
                            continue
                        total += dp(pos + 1, sum_digits + d, prod_digits * d, True, next_tight)

                return total

            return dp(0, 0, 1, False, True)

        def count_beautiful(n: int) -> int:
            if n <= 0:
                return 0
            return n - count_non_beautiful(n)

        return count_beautiful(r) - count_beautiful(l - 1)

