class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if k == n:
            return [0] * n

        children = [{}]
        cnt = [0]
        depth = [0]
        terminal = [0] * n

        for idx, w in enumerate(words):
            v = 0
            cnt[0] += 1
            for ch in w:
                nxt = children[v].get(ch)
                if nxt is None:
                    nxt = len(cnt)
                    children[v][ch] = nxt
                    children.append({})
                    cnt.append(0)
                    depth.append(depth[v] + 1)
                v = nxt
                cnt[v] += 1
            terminal[idx] = v

        m = len(cnt)
        terminal_node = [False] * m
        for t in terminal:
            terminal_node[t] = True

        global_good = 0
        for v in range(m):
            if cnt[v] >= k + 1:
                global_good = max(global_good, depth[v])

        max_depth = max(depth) if depth else 0
        counts = [0] * (max_depth + 1)
        heap = []

        for v in range(m):
            if cnt[v] == k:
                d = depth[v]
                if counts[d] == 0:
                    heapq.heappush(heap, -d)
                counts[d] += 1

        ans_node = {}
        stack = [(0, 0)]  # (node, state), state 0 = enter, 1 = exit

        while stack:
            v, state = stack.pop()
            if state == 0:
                d = depth[v]

                if cnt[v] == k:
                    counts[d] -= 1

                if terminal_node[v]:
                    while heap and counts[-heap[0]] == 0:
                        heapq.heappop(heap)
                    best_out = -heap[0] if heap else 0
                    ans_node[v] = max(global_good, best_out)

                stack.append((v, 1))
                for u in children[v].values():
                    stack.append((u, 0))
            else:
                d = depth[v]
                if cnt[v] == k:
                    if counts[d] == 0:
                        heapq.heappush(heap, -d)
                    counts[d] += 1

        return [ans_node[terminal[i]] for i in range(n)]

