import sys
from collections import deque


class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        self.g[fr].append([to, cap, len(self.g[to])])
        self.g[to].append([fr, 0, len(self.g[fr]) - 1])

    def dfs(self, v, t, f):
        if v == t:
            return f
        g = self.g
        level = self.level
        it = self.it
        while it[v] < len(g[v]):
            e = g[v][it[v]]
            if e[1] > 0 and level[v] < level[e[0]]:
                ret = self.dfs(e[0], t, min(f, e[1]))
                if ret > 0:
                    e[1] -= ret
                    g[e[0]][e[2]][1] += ret
                    return ret
            it[v] += 1
        return 0

    def max_flow(self, s, t, limit):
        flow = 0
        n = self.n
        g = self.g
        while flow < limit:
            self.level = [-1] * n
            q = deque([s])
            self.level[s] = 0
            while q:
                v = q.popleft()
                for e in g[v]:
                    if e[1] > 0 and self.level[e[0]] < 0:
                        self.level[e[0]] = self.level[v] + 1
                        q.append(e[0])
            if self.level[t] < 0:
                break
            self.it = [0] * n
            while flow < limit:
                f = self.dfs(s, t, limit - flow)
                if f == 0:
                    break
                flow += f
        return flow


def main():
    sys.setrecursionlimit(1000000)
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return

    it = iter(data)
    N = next(it)
    M = next(it)
    K = next(it)

    edges = []
    for _ in range(M):
        u = next(it) - 1
        v = next(it) - 1
        edges.append((u, v))

    ans = 0
    INF = 10**9

    for L in range(1, N):  # maximum possible distance is at most N-1
        V = N * L + 2
        s = N * L
        t = s + 1
        dinic = Dinic(V)

        def node(v, i):
            return v * L + i

        # source vertex 1 must be in all S_i
        for i in range(L):
            dinic.add_edge(s, node(0, i), INF)
            # sink vertex N must not be in any S_i
            dinic.add_edge(node(N - 1, i), t, INF)

        # monotonicity: v in S_i => v in S_{i+1}
        for v in range(N):
            for i in range(L - 1):
                dinic.add_edge(node(v, i), node(v, i + 1), INF)

        for u, v in edges:
            # cost: u in S_i and v not in S_i
            for i in range(L):
                dinic.add_edge(node(u, i), node(v, i), 1)

            # implication: u in S_i => v in S_{i+1}
            for i in range(L - 1):
                dinic.add_edge(node(u, i), node(v, i + 1), INF)

        flow = dinic.max_flow(s, t, K + 1)
        if flow <= K:
            ans = L

    print(ans)


