class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        if m == 0:
            return n * (n + 1) // 2

        pairs_by_a = [[] for _ in range(n + 1)]
        max_id_for_b = [-1] * (n + 2)
        max_a_for_b = [-1] * (n + 2)

        for i, (x, y) in enumerate(conflictingPairs):
            if x < y:
                a, b = x, y
            else:
                a, b = y, x
            pairs_by_a[a].append((b, i))
            if a > max_a_for_b[b]:
                max_a_for_b[b] = a
                max_id_for_b[b] = i

        INF = n + 1
        m1 = INF
        m2 = INF
        count1 = 0
        base = 0
        gain = [0] * m

        for l in range(n, 0, -1):
            for b, _ in pairs_by_a[l]:
                if b < m1:
                    m2 = m1
                    m1 = b
                    count1 = 1
                elif b == m1:
                    count1 += 1
                elif b < m2:
                    m2 = b

            base += m1 - l

            if count1 == 1:
                second = m2 if m2 != INF else INF
                gain[max_id_for_b[m1]] += second - m1

        return base + max(gain)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1
        ans = [None] * L
        forced = [False] * L

        # Apply all 'T' constraints
        for i, ch in enumerate(str1):
            if ch == 'T':
                for k in range(m):
                    pos = i + k
                    c = str2[k]
                    if ans[pos] is None:
                        ans[pos] = c
                        forced[pos] = True
                    elif ans[pos] != c:
                        return ""

        # Fill all unconstrained positions with the smallest character 'a'
        for pos in range(L):
            if ans[pos] is None:
                ans[pos] = 'a'

        # Process 'F' constraints from left to right
        for i, ch in enumerate(str1):
            if ch == 'F':
                # Check if the current substring equals str2
                equal = True
                for k in range(m):
                    if ans[i + k] != str2[k]:
                        equal = False
                        break

                if equal:
                    # Need to break this equality by changing the rightmost
                    # unconstrained (not forced by any 'T') position to 'b'
                    j = i + m - 1
                    while j >= i and forced[j]:
                        j -= 1

                    if j < i:
                        return ""

                    ans[j] = 'b'

        return ''.join(ans)

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        INF = 10**18

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            if fact[i - 1] > INF // i:
                fact[i] = INF
            else:
                fact[i] = fact[i - 1] * i

        def mul_cap(a: int, b: int) -> int:
            if a == 0 or b == 0:
                return 0
            if a > INF // b:
                return INF
            return a * b

        def count_completions(rem_odd: int, rem_even: int, next_parity: int) -> int:
            m = rem_odd + rem_even
            if next_parity == 1:
                odd_slots = (m + 1) // 2
                even_slots = m // 2
            else:
                even_slots = (m + 1) // 2
                odd_slots = m // 2

            if rem_odd != odd_slots or rem_even != even_slots:
                return 0

            return mul_cap(fact[rem_odd], fact[rem_even])

        unused = list(range(1, n + 1))
        rem_odd = (n + 1) // 2
        rem_even = n // 2

        res = []
        prev_parity = None

        for pos in range(n):
            chosen = None

            for val in unused:
                p = val & 1

                if pos > 0 and p == prev_parity:
                    continue

                r_odd = rem_odd - (1 if p == 1 else 0)
                r_even = rem_even - (1 if p == 0 else 0)
                next_parity = 1 - p

                cnt = count_completions(r_odd, r_even, next_parity)

                if cnt >= k:
                    chosen = val
                    break

                k -= cnt

            if chosen is None:
                return []

            res.append(chosen)
            unused.remove(chosen)

            if chosen & 1:
                rem_odd -= 1
            else:
                rem_even -= 1

            prev_parity = chosen & 1

        return res

