def main():
    input = sys.stdin.buffer.readline
    N, X = map(int, input().split())

    U = [0] * N
    D = [0] * N
    total = 0
    min_sum = 10**30

    for i in range(N):
        u, d = map(int, input().split())
        U[i] = u
        D[i] = d
        total += u + d
        s = u + d
        if s < min_sum:
            min_sum = s

    def feasible(H):
        l = H - D[0]
        if l < 0:
            l = 0
        r = U[0]
        if H < r:
            r = H

        left = l
        right = r
        if left > right:
            return False

        for i in range(1, N):
            l = H - D[i]
            if l < 0:
                l = 0
            r = U[i]
            if H < r:
                r = H

            left -= X
            if left < l:
                left = l

            right += X
            if right > r:
                right = r

            if left > right:
                return False

        return True

    lo = 0
    hi = min_sum + 1

    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid

    ans = total - N * lo
