import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    out = []
    for _ in range(T):
        N = int(next(it))
        A = next(it)
        B = next(it)
        p = [i + 1 for i, c in enumerate(A) if c == '1']
        b = [i + 1 for i, c in enumerate(B) if c == '1']
        k = len(p)
        s = len(b)
        if k < s:
            out.append("-1")
            continue

        L = [0] * s
        R = [0] * s

        def check(T: int) -> bool:
            # compute L[j] = first index with p[idx] >= b[j] - T
            idxL = 0
            for j in range(s):
                limit = b[j] - T
                while idxL < k and p[idxL] < limit:
                    idxL += 1
                L[j] = idxL
            # compute R[j] = last index with p[idx] <= b[j] + T
            idxR = k - 1
            for j in range(s - 1, -1, -1):
                limit = b[j] + T
                while idxR >= 0 and p[idxR] > limit:
                    idxR -= 1
                R[j] = idxR

            for j in range(s):
                if L[j] > R[j]:
                    return False

            prev = -1
            for j in range(s - 1):
                start = prev + 1
                if start >= k or start < L[j]:
                    return False
                i0 = L[j + 1] - 1
                if i0 < start:
                    i0 = start
                max_i = R[j]
                if max_i > k - 2:
                    max_i = k - 2
                if i0 > max_i:
                    return False

                i = i0
                bj = b[j]
                bj1 = b[j + 1]
                req_base = bj1 - bj
                while i <= max_i:
                    gap = p[i + 1] - p[i]
                    req = req_base
                    if (T - bj + p[i]) & 1:
                        req += 1
                    if gap >= req:
                        break
                    i += 1
                if i > max_i:
                    return False
                prev = i

            start = prev + 1
            if start >= k or start < L[s - 1]:
                return False
            if k - 1 > R[s - 1]:
                return False
            return True

        ans = -1
        for parity in (0, 1):
            max_x = (N - parity) // 2
            if max_x < 0:
                continue
            lo, hi = 0, max_x
            while lo < hi:
                mid = (lo + hi) // 2
                T = 2 * mid + parity
                if check(T):
                    hi = mid
                else:
                    lo = mid + 1
            T = 2 * lo + parity
            if T <= N and check(T):
                if ans == -1 or T < ans:
                    ans = T
        out.append(str(ans))
    sys.stdout.write("\n".join(out))

