class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        S = side
        C = 4 * S
        t = []
        for x, y in points:
            if y == 0:
                pos = x
            elif x == S:
                pos = S + y
            elif y == S:
                pos = 3 * S - x
            else:
                pos = 4 * S - y
            t.append(pos)
        t.sort()
        n = len(t)
        t2 = t + [x + C for x in t]

        def can(D: int) -> bool:
            if D <= 0:
                return True
            next_idx = [0] * (2 * n)
            j = 0
            for i in range(2 * n):
                if j < i:
                    j = i
                target = t2[i] + D
                while j < 2 * n and t2[j] < target:
                    j += 1
                next_idx[i] = j

            for i in range(n):
                cur = i
                for _ in range(k - 1):
                    cur = next_idx[cur]
                    if cur >= 2 * n:
                        break
                if cur < i + n and cur < 2 * n:
                    if t2[cur] <= t2[i] + C - D:
                        return True
            return False

        low, high = 0, S
        while low < high:
            mid = (low + high + 1) // 2
            if can(mid):
                low = mid
            else:
                high = mid - 1
        return low

