class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        # Directions in clockwise order:
        # 0: down-right, 1: down-left, 2: up-left, 3: up-right
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # tails[d][r][c] = maximum number of additional cells after (r,c)
        # moving in direction d, following the alternating 2,0 sequence.
        tails = []
        for dr, dc in dirs:
            tail = [[0] * m for _ in range(n)]
            if dr == 1:
                r_range = range(n - 1, -1, -1)
            else:
                r_range = range(n)
            if dc == 1:
                c_range = range(m - 1, -1, -1)
            else:
                c_range = range(m)

            for r in r_range:
                row = grid[r]
                tail_row = tail[r]
                for c in c_range:
                    val = row[c]
                    nr = r + dr
                    nc = c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        expected = 0 if val == 2 else 2
                        if grid[nr][nc] == expected:
                            tail_row[c] = 1 + tail[nr][nc]
            tails.append(tail)

        ans = 0

        # For each possible initial direction, compute prefix DP ending at each cell,
        # then combine with the clockwise turn tail.
        for d in range(4):
            dr, dc = dirs[d]
            pref = [[0] * m for _ in range(n)]

            if dr == 1:
                r_range = range(n)
            else:
                r_range = range(n - 1, -1, -1)
            if dc == 1:
                c_range = range(m)
            else:
                c_range = range(m - 1, -1, -1)

            post_tail = tails[(d + 1) & 3]

            for r in r_range:
                row = grid[r]
                pref_row = pref[r]
                post_tail_row = post_tail[r]
                for c in c_range:
                    val = row[c]
                    if val == 1:
                        l = 1
                    else:
                        l = 0
                        pr = r - dr
                        pc = c - dc
                        if 0 <= pr < n and 0 <= pc < m:
                            plen = pref[pr][pc]
                            if val == 2:
                                if plen & 1:
                                    l = plen + 1
                            elif val == 0:
                                if plen and (plen & 1) == 0:
                                    l = plen + 1

                    pref_row[c] = l
                    if l > ans:
                        ans = l
                    if l:
                        total = l + post_tail_row[c]
                        if total > ans:
                            ans = total

        return ans

