class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        def kmp_search(text, pat):
            m = len(pat)
            if m == 0:
                return []
            lps = [0] * m
            length = 0
            i = 1
            while i < m:
                if pat[i] == pat[length]:
                    length += 1
                    lps[i] = length
                    i += 1
                else:
                    if length != 0:
                        length = lps[length - 1]
                    else:
                        lps[i] = 0
                        i += 1

            res = []
            i = 0
            j = 0
            n = len(text)
            while i < n:
                if text[i] == pat[j]:
                    i += 1
                    j += 1
                    if j == m:
                        res.append(i - m)
                        j = lps[j - 1]
                else:
                    if j != 0:
                        j = lps[j - 1]
                    else:
                        i += 1
            return res

        parts = p.split('*')
        A, B, C = parts[0], parts[1], parts[2]
        la, lb, lc = len(A), len(B), len(C)

        occA = occB = occC = []
        if la > 0:
            occA = kmp_search(s, A)
            if not occA:
                return -1
        if lb > 0:
