import sys

MOD = 998244353


def factorize(x):
    res = []
    d = 2
    while d * d <= x:
        if x % d == 0:
            cnt = 0
            while x % d == 0:
                x //= d
                cnt += 1
            res.append((d, cnt))
        d += 1
    if x > 1:
        res.append((x, 1))
    return res


def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return

    N = data[0]
    A = data[1:1 + N - 1]

    # prime -> list of exponents for each edge
    prime_dict = {}
    for i, a in enumerate(A):
        for p, e in factorize(a):
            if p not in prime_dict:
                prime_dict[p] = [0] * (N - 1)
            prime_dict[p][i] = e

    ans = 1

    for p, e_list in prime_dict.items():
        S = sum(e_list)
        if S == 0:
            continue

        powp = [1] * (S + 1)
        for h in range(1, S + 1):
            powp[h] = powp[h - 1] * p % MOD

        # dp0[h] : paths whose minimum so far is > 0, current height h
        # dp1[h] : paths that have already touched height 0, current height h
        dp0 = [0] * (S + 1)
        dp1 = [0] * (S + 1)

        # vertex 1
        for h in range(S + 1):
            val = powp[h]
            if h == 0:
                dp1[h] = val
            else:
                dp0[h] = val

        for e in e_list:
            new0 = [0] * (S + 1)
            new1 = [0] * (S + 1)

            if e == 0:
                for h in range(S + 1):
                    v0 = dp0[h]
                    v1 = dp1[h]
                    if v0 == 0 and v1 == 0:
                        continue
                    mult = powp[h]
                    if h == 0:
                        new1[h] = (new1[h] + (v0 + v1) * mult) % MOD
                    else:
                        if v0:
                            new0[h] = (new0[h] + v0 * mult) % MOD
                        if v1:
                            new1[h] = (new1[h] + v1 * mult) % MOD
            else:
                for h in range(S + 1):
                    v0 = dp0[h]
                    v1 = dp1[h]
                    if v0 == 0 and v1 == 0:
                        continue

                    # +e
                    h2 = h + e
                    if h2 <= S:
                        mult = powp[h2]
                        if v0:
                            new0[h2] = (new0[h2] + v0 * mult) % MOD
                        if v1:
                            new1[h2] = (new1[h2] + v1 * mult) % MOD

                    # -e
                    h2 = h - e
                    if h2 >= 0:
                        mult = powp[h2]
                        if h2 == 0:
                            new1[0] = (new1[0] + (v0 + v1) * mult) % MOD
                        else:
                            if v0:
                                new0[h2] = (new0[h2] + v0 * mult) % MOD
                            if v1:
                                new1[h2] = (new1[h2] + v1 * mult) % MOD

            dp0, dp1 = new0, new1

        F = sum(dp1) % MOD
        ans = ans * F % MOD

    print(ans)


