class Solution:
    def countSubstrings(self, s: str) -> int:
        cnt = [[0] * i for i in range(10)]
        ans = 0

        for ch in s:
            x = ord(ch) - 48

            for m in range(1, 10):
                old = cnt[m]
                new = [0] * m
                new[x % m] = 1

                for r, c in enumerate(old):
                    if c:
                        new[(r * 10 + x) % m] += c

                cnt[m] = new

            if x:
                ans += cnt[x][0]

        return ans

