def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]

    MOD = 998244353
    L = 1 << N
    scodes = [ord(ch) - 97 for ch in S]

    # trans[mask][c] = next state when appending character c
    trans = [[0] * 26 for _ in range(L)]

    for mask in range(L):
        old = [0] * (N + 1)
        for j in range(1, N + 1):
            old[j] = old[j - 1] + ((mask >> (j - 1)) & 1)

        for c in range(26):
            new = [0] * (N + 1)
            for j in range(1, N + 1):
                val = old[j]
                if new[j - 1] > val:
                    val = new[j - 1]
                if scodes[j - 1] == c:
                    v2 = old[j - 1] + 1
                    if v2 > val:
                        val = v2
                new[j] = val

            nmask = 0
            for j in range(1, N + 1):
                if new[j] > new[j - 1]:
                    nmask |= 1 << (j - 1)

            trans[mask][c] = nmask

    dp = [0] * L
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * L
        for mask, val in enumerate(dp):
            if val == 0:
                continue
            row = trans[mask]
            for c in range(26):
                nxt = row[c]
                nv = ndp[nxt] + val
                if nv >= MOD:
                    nv -= MOD
                ndp[nxt] = nv
        dp = ndp

    ans = [0] * (N + 1)
    for mask, val in enumerate(dp):
        k = 0
        x = mask
        while x:
            k += x & 1
            x >>= 1
        ans[k] = (ans[k] + val) % MOD

    sys.stdout.write(" ".join(map(str, ans)))

