import sys
from collections import deque

sys.setrecursionlimit(1_000_000)

def solve():
    input = sys.stdin.readline
    N, M, S, T = map(int, input().split())
    S -= 1
    T -= 1
    adj = [[] for _ in range(N)]
    for _ in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    # BFS from S and T
    def bfs(start):
        dist = [-1] * N
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        return dist

    distS = bfs(S)
    distT = bfs(T)

    # Tarjan biconnected components
    disc = [-1] * N
    low = [-1] * N
    stack = []
    blocks = []
    time = 0

    def dfs(u, parent):
        nonlocal time
        disc[u] = low[u] = time
        time += 1
        for v in adj[u]:
            if v == parent:
                continue
            if disc[v] == -1:
                stack.append((u, v))
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] >= disc[u]:
                    block_edges = []
                    while True:
                        e = stack.pop()
                        block_edges.append(e)
                        if e == (u, v):
                            break
                    verts = set()
                    for a, b in block_edges:
                        verts.add(a)
                        verts.add(b)
                    blocks.append(list(verts))
            elif disc[v] < disc[u] and v != parent:
                stack.append((u, v))
                low[u] = min(low[u], disc[v])

    dfs(0, -1)

    on_cycle = [False] * N
    for verts in blocks:
        if len(verts) >= 3:
            for v in verts:
                on_cycle[v] = True

    ans = float('inf')
    for v in range(N):
        if on_cycle[v]:
            cost = 2 * (distS[v] + distT[v]) + 4
            if cost < ans:
                ans = cost

    B = len(blocks)
    tree = [[] for _ in range(N + B)]
    for i, verts in enumerate(blocks):
        node = N + i
        for v in verts:
            tree[v].append(node)
            tree[node].append(v)

    # BFS in block-cut tree to find path from S to T
    parent = [-1] * (N + B)
    q = deque([S])
    parent[S] = -2
    while q:
        u = q.popleft()
        if u == T:
            break
        for v in tree[u]:
            if parent[v] == -1:
                parent[v] = u
                q.append(v)

    if parent[T] == -1:
        print(-1)
        return

    path = []
    cur = T
    while cur != -2:
        path.append(cur)
        cur = parent[cur]
    path.reverse()

    # Process cyclic blocks on the path
    for i in range(len(path)):
        node = path[i]
        if node >= N:
            b_idx = node - N
            verts = blocks[b_idx]
            if len(verts) < 3:
                continue
            a = path[i - 1] if i > 0 else None
            b = path[i + 1] if i + 1 < len(path) else None
            if a is None or b is None:
                continue

            block_set = set(verts)

            def bfs_restricted(start, target, removed=None):
                dist = {start: 0}
                q = deque([start])
                while q:
                    u = q.popleft()
                    if u == target:
                        return dist[u], dist
                    for v in adj[u]:
                        if v in block_set and (removed is None or v not in removed):
                            if v not in dist:
                                dist[v] = dist[u] + 1
                                q.append(v)
                return -1, dist

            d1, dist_dict = bfs_restricted(a, b)
            if d1 == -1:
                continue

            # reconstruct shortest path from a to b
            path_ab = []
            cur = b
            while cur != a:
                path_ab.append(cur)
                for v in adj[cur]:
                    if v in block_set and v in dist_dict and dist_dict[v] == dist_dict[cur] - 1:
                        cur = v
                        break
            path_ab.append(a)

            removed = set(path_ab[1:-1])
            d2, _ = bfs_restricted(a, b, removed)
            if d2 != -1:
                cost = 2 * (distS[a] + distT[b]) + d1 + d2
                if cost < ans:
                    ans = cost

    if ans == float('inf'):
        print(-1)
    else:
        print(ans)


