    solve()

import sys

def build_primes(limit):
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            start = i * i
            step = i
            sieve[start:limit + 1:step] = b'\x00' * (((limit - start) // step) + 1)
    return [i for i in range(limit + 1) if sieve[i]]

primes = build_primes(31623)

def factorize(n):
    res = []
    for p in primes:
        if p * p > n:
            break
        if n % p == 0:
            e = 0
            while n % p == 0:
                n //= p
                e += 1
            res.append((p, e))
    if n > 1:
        res.append((n, 1))
    return res

def inv_mod(a, m):
    a %= m
    if m == 1:
        return 0
    x0, x1 = 1, 0
    b = m
    while b:
        q = a // b
        a, b = b, a - q * b
        x0, x1 = x1, x0 - q * x1
    return x0 % m

def crt(residues):
    x = 0
    mod = 1
    for a, m in residues:
        inv = inv_mod(mod % m, m)
        t = ((a - x) % m) * inv % m
        x = x + mod * t
        mod *= m
        x %= mod
    return x, mod

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    T = int(data[0])
    out = []
    idx = 1

    for _ in range(T):
        N = int(data[idx])
        idx += 1

        if N == 1:
            out.append("1 1")
            continue

        if N == 2:
            out.append("2 3")
            continue

        factors = factorize(N)

        # If N is odd, or divisible by 4, use a separate 2-power modulus if needed.
        if N % 4 == 0 or N % 2 == 1:
            residues = []
            for q, e in factors:
                if q == 2:
                    m = 1 << (e + 2)      # 2^(e+2)
                    a = 5 % m             # order 2^e modulo 2^(e+2)
                else:
                    m = q ** (e + 1)
                    a = (1 + q) % m       # order q^e modulo q^(e+1)
                residues.append((a, m))
            A, M = crt(residues)
            out.append(f"{A} {M}")

        else:
            # N is even but not divisible by 4, and N > 2.
            # Let one odd component provide the extra factor 2.
            residues = []
            chosen = False
            for q, e in factors:
                if q == 2:
                    continue
                m = q ** (e + 1)
                if not chosen:
                    a = (-(1 + q)) % m   # order 2 * q^e modulo q^(e+1)
                    chosen = True
                else:
                    a = (1 + q) % m      # order q^e modulo q^(e+1)
                residues.append((a, m))
            A, M = crt(residues)
            out.append(f"{A} {M}")

    sys.stdout.write("\n".join(out))

