def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, X = data[0], data[1]
    items = [[], [], []]
    sums = [0, 0, 0]

    idx = 2
    for _ in range(N):
        v = data[idx]
        a = data[idx + 1]
        c = data[idx + 2]
        idx += 3
        items[v - 1].append((c, a))
        sums[v - 1] += a

    dps = []
    for group in items:
        dp = [0] * (X + 1)
        for c, a in group:
            for cap in range(X, c - 1, -1):
                val = dp[cap - c] + a
                if val > dp[cap]:
                    dp[cap] = val
        dps.append(dp)

    def feasible(t):
        total_cost = 0
        for dp in dps:
            if dp[X] < t:
                return False

            lo, hi = 0, X
            while lo < hi:
                mid = (lo + hi) // 2
                if dp[mid] >= t:
                    hi = mid
                else:
                    lo = mid + 1
            total_cost += lo
            if total_cost > X:
                return False
        return True

    lo, hi = 0, min(sums)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1

    print(lo)

