class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        N = m * n

        def one_dim(L: int) -> int:
            return (L * (L - 1) * (L + 1) // 6) % MOD

        row_contrib = (n * n % MOD) * one_dim(m) % MOD
        col_contrib = (m * m % MOD) * one_dim(n) % MOD
        total_distance = (row_contrib + col_contrib) % MOD

        fact = [1] * (N + 1)
        for i in range(1, N + 1):
            fact[i] = fact[i - 1] * i % MOD

        invfact = [1] * (N + 1)
        invfact[N] = pow(fact[N], MOD - 2, MOD)
        for i in range(N, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        def comb(n: int, r: int) -> int:
            if r < 0 or r > n:
                return 0
            return fact[n] * invfact[r] % MOD * invfact[n - r] % MOD

        arrangements = comb(N - 2, k - 2)

        return total_distance * arrangements % MOD

import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    P = int(data[1])

    max_edges = N * (N - 1) // 2
    maxC = max(max_edges, N)

    # binomial coefficients modulo P
    C = [[0] * (maxC + 1) for _ in range(maxC + 1)]
    for i in range(maxC + 1):
        C[i][0] = 1
        C[i][i] = 1
        for j in range(1, i):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P

    # cross_terms[a][b] = expansion of (y^a - 1)^b
    cross_terms = [[None] * (N + 1) for _ in range(N + 1)]
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            terms = []
            for j in range(b + 1):
                shift = a * (b - j)
                coef = C[b][j]
                if j & 1:
                    coef = (-coef) % P
                terms.append((shift, coef))
            cross_terms[a][b] = terms

    # dp[s] maps (last_layer_size, even_minus_odd, last_parity) -> polynomial in y
    # polynomial length = s*(s-1)//2 + 1
    dp = [None] * (N + 1)
    dp[1] = {(1, 1, 0): [1]}

    for s in range(1, N):
        cur = dp[s]
        if cur is None:
            continue

        remaining = N - s

        for (a, d, par), poly in cur.items():
            nz = []
            for K, val in enumerate(poly):
                v = val % P
                if v:
                    nz.append((K, v))
            if not nz:
                continue

            for b in range(1, remaining + 1):
                new_s = s + b
                new_remaining = N - new_s

                if par == 0:
                    new_d = d - b
                else:
                    new_d = d + b

                if abs(new_d) > new_remaining:
                    continue
                if (new_remaining - new_d) & 1:
                    continue

                choose = C[remaining][b]
                if choose == 0:
                    continue

                key = (b, new_d, 1 - par)
                tdict = dp[new_s]
                if tdict is None:
                    tdict = {}
                    dp[new_s] = tdict

                target = tdict.get(key)
                if target is None:
                    target = [0] * (new_s * (new_s - 1) // 2 + 1)
                    tdict[key] = target

                internal_shift = b * (b - 1) // 2
                terms = cross_terms[a][b]

                for shift_cross, coef0 in terms:
                    coef = (coef0 * choose) % P
                    if coef == 0:
                        continue
                    shift = shift_cross + internal_shift
                    for K, val in nz:
                        target[K + shift] += val * coef

        dp[s] = None

    final_y = [0] * (max_edges + 1)
    if dp[N] is not None:
        for (a, d, par), poly in dp[N].items():
            if d == 0:
                for K, val in enumerate(poly):
                    v = val % P
                    if v:
                        final_y[K] = (final_y[K] + v) % P

    ans = []
    for M in range(N - 1, max_edges + 1):
        total = 0
        for K in range(M, max_edges + 1):
            c = final_y[K]
            if c:
                total = (total + c * C[K][M]) % P
        ans.append(str(total))

    print(" ".join(ans))


