import sys


def mat_mul(A, B, mod):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        Ci = C[i]
        Ai = A[i]
        for k in range(n):
            aik = Ai[k]
            if aik:
                Bk = B[k]
                for j, bkj in enumerate(Bk):
                    Ci[j] += aik * bkj
        for j in range(n):
            Ci[j] %= mod
    return C


def mat_pow(A, exp, mod):
    n = len(A)
    result = None
    base = A
    while exp > 0:
        if exp & 1:
            if result is None:
                result = [row[:] for row in base]
            else:
                result = mat_mul(result, base, mod)
        exp >>= 1
        if exp:
            base = mat_mul(base, base, mod)

    if result is None:
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            result[i][i] = 1 % mod
    return result


def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    p = int(next(it))

    A = []
    K = 0
    for _ in range(N):
        row = []
        for _ in range(N):
            v = int(next(it))
            row.append(v)
            if v == 0:
                K += 1
        A.append(row)

    if p == 2:
        C = [[1 if A[i][j] == 0 else A[i][j] for j in range(N)] for i in range(N)]
        C2 = mat_mul(C, C, p)
        out = [" ".join(map(str, row)) for row in C2]
        sys.stdout.write("\n".join(out))
        return

    F = [[A[i][j] if A[i][j] != 0 else 0 for j in range(N)] for i in range(N)]

    Fp = mat_pow(F, p, p)
    T = [row[:] for row in Fp]

    for u in range(N):
        for v in range(N):
            if A[u][v] == 0:
                if u == v:
                    # zero loop at u
                    for i in range(N):
                        T[i][u] = (T[i][u] + F[i][u]) % p
                    for j in range(N):
                        T[u][j] = (T[u][j] + F[u][j]) % p
                else:
                    if p == 3:
                        T[u][v] = (T[u][v] + F[v][u]) % p

    if K % 2 == 1:
        for i in range(N):
            row = T[i]
            for j in range(N):
                row[j] = (-row[j]) % p

    out = [" ".join(map(str, row)) for row in T]
    sys.stdout.write("\n".join(out))


