from typing import List
from bisect import bisect_left

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        arr = []
        for idx, (l, r, w) in enumerate(intervals):
            arr.append((r, l, w, idx))
        arr.sort(key=lambda x: x[0])

        rights = [x[0] for x in arr]
        p = [0] * n
        for i in range(n):
            l = arr[i][1]
            pos = bisect_left(rights, l)
            p[i] = pos - 1

        dp_prev = [(0, ()) for _ in range(n + 1)]

        for _ in range(4):
            cur = [(0, ()) for _ in range(n + 1)]
            for i in range(1, n + 1):
                best_w, best_t = cur[i - 1]
                r, l, w, idx = arr[i - 1]
                prev_w, prev_t = dp_prev[p[i - 1] + 1]
                cand_w = prev_w + w
                cand_t = tuple(sorted(prev_t + (idx,)))

                if cand_w > best_w:
                    cur[i] = (cand_w, cand_t)
                elif cand_w == best_w:
                    if cand_t < best_t:
                        cur[i] = (cand_w, cand_t)
                    else:
                        cur[i] = (best_w, best_t)
                else:
                    cur[i] = (best_w, best_t)
            dp_prev = cur

        return list(dp_prev[n][1])

