    N, K = data[0], data[1]
    A = data[2:2 + N]

    total_xor = 0
    for v in A:
        total_xor ^= v

    # Enumerate the smaller side: chosen elements or excluded elements.
    if K <= N - K:
        R = K
        mode = 0  # maximize XOR of chosen elements directly
    else:
        R = N - K
        mode = 1  # maximize total_xor XOR (XOR of excluded elements)

    best = -1
    n = N
    arr = A

    if mode == 0:
        def dfs(start, left, cur):
            nonlocal best
            if left == 0:
                if cur > best:
                    best = cur
                return
            end = n - left + 1
            for i in range(start, end):
                dfs(i + 1, left - 1, cur ^ arr[i])
    else:
        def dfs(start, left, cur):
            nonlocal best
            if left == 0:
                val = total_xor ^ cur
                if val > best:
                    best = val
                return
            end = n - left + 1
            for i in range(start, end):
                dfs(i + 1, left - 1, cur ^ arr[i])

    dfs(0, R, 0)
    print(best)

