import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    N = int(data[0])
    A = [0] + [int(x) for x in data[1:1+N]]
    P = [0] * (N + 1)
    for i in range(1, N + 1):
        P[i] = P[i - 1] + A[i]

    # Build max Cartesian tree with tie-breaking: leftmost maximum is higher.
    left = [-1] * (N + 1)
    right = [-1] * (N + 1)
    stack = []
    for i in range(1, N + 1):
        last = -1
        while stack and A[stack[-1]] < A[i]:
            last = stack.pop()
        if stack:
            right[stack[-1]] = i
        if last != -1:
            left[i] = last
        stack.append(i)
    root = stack[0]

    # Compute segment [L[i], R[i]] for each node.
    L = [0] * (N + 1)
    R = [0] * (N + 1)
    order = []
    st = [root]
    while st:
        v = st.pop()
        order.append(v)
        if left[v] != -1:
            st.append(left[v])
        if right[v] != -1:
            st.append(right[v])
    for v in reversed(order):
        L[v] = v
        R[v] = v
        if left[v] != -1:
            L[v] = L[left[v]]
        if right[v] != -1:
            R[v] = R[right[v]]

    # Sum of each segment.
    S = [0] * (N + 1)
    for i in range(1, N + 1):
        S[i] = P[R[i]] - P[L[i] - 1]

    # reach[i] = highest ancestor reachable starting from node i with sum S[i].
    reach = [0] * (N + 1)
    reach[root] = root
    st = [root]
    while st:
        v = st.pop()
        for child in (left[v], right[v]):
            if child != -1:
                if S[child] > A[v]:
                    reach[child] = reach[v]
                else:
                    reach[child] = child
                st.append(child)

    # Answer for each starting position.
    ans = [0] * (N + 1)
    for i in range(1, N + 1):
        if L[i] < i or (R[i] > i and A[i + 1] < A[i]):
            ans[i] = S[reach[i]]
        else:
            ans[i] = A[i]

    sys.stdout.write(' '.join(map(str, ans[1:])))

if __name__ == '__main__':
    solve()

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold
        parent = list(range(T + 1))
        rank = [0] * (T + 1)

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1

        actual = []
        isolated_large = 0

        for x in nums:
            if x <= T:
                actual.append(x)
                for multiple in range(x, T + 1, x):
                    union(x, multiple)
            else:
                isolated_large += 1

        roots = set()
        for x in actual:
            roots.add(find(x))

        return len(roots) + isolated_large
